import { auth } from "@/auth/server";
import { toNextJsHandler } from "better-auth/next-js";

export const { POST, GET } = toNextJsHandler(auth);

import { Ratelimit } from "@upstash/ratelimit";
import { Redis } from "@upstash/redis";
import { webEnv } from "@/env/web";

const redis = new Redis({
	url: webEnv.UPSTASH_REDIS_REST_URL,
	token: webEnv.UPSTASH_REDIS_REST_TOKEN,
});

export const baseRateLimit = new Ratelimit({
	redis,
	limiter: Ratelimit.slidingWindow(100, "1 m"), // 100 requests per minute
	analytics: true,
	prefix: "rate-limit",
});

export async function checkRateLimit({ request }: { request: Request }) {
	const ip = request.headers.get("x-forwarded-for") ?? "anonymous";
	const { success } = await baseRateLimit.limit(ip);
	return { success, limited: !success };
}

import {
	afterEach,
	beforeEach,
	describe,
	expect,
	mock,
	test,
} from "bun:test";
import {
	decodePersistedKeybindingsState,
	migratePersistedKeybindingsState,
	parseImportedKeybindings,
	serializeKeybindingsState,
} from "../persistence";

describe("keybinding persistence", () => {
	let warnSpy: ReturnType<typeof mock>;
	let originalWarn: typeof console.warn;

	beforeEach(() => {
		originalWarn = console.warn;
		warnSpy = mock(() => {});
		console.warn = warnSpy;
	});

	afterEach(() => {
		console.warn = originalWarn;
	});

	test("migrates legacy persisted keybindings before decoding them", () => {
		const migrated = migratePersistedKeybindingsState({
			state: {
				keybindings: {
					s: "split-selected",
					"ctrl+v": "paste-selected",
				},
				isCustomized: true,
			},
			fromVersion: 2,
		});

		const decoded = decodePersistedKeybindingsState({ state: migrated });
		expect(decoded).not.toBeNull();
		if (!decoded) throw new Error("Expected migrated keybindings to decode");

		expect(decoded.isCustomized).toBe(true);
		expect(decoded.keybindings.get("s")).toBe("split");
		expect(decoded.keybindings.get("ctrl+v")).toBe("paste-copied");
		expect(decoded.keybindings.get("escape")).toBe("cancel-interaction");
		expect(warnSpy).not.toHaveBeenCalled();
	});

	test("filters invalid persisted entries at the boundary and warns", () => {
		const decoded = decodePersistedKeybindingsState({
			state: {
				keybindings: {
					space: "toggle-play",
					"shift+bogus": "toggle-play",
					"ctrl+v": "not-an-action",
				},
				isCustomized: false,
			},
		});

		expect(decoded).not.toBeNull();
		if (!decoded) throw new Error("Expected persisted keybindings to decode");

		expect(Array.from(decoded.keybindings.entries())).toEqual([
			["space", "toggle-play"],
		]);
		expect(warnSpy).toHaveBeenCalledTimes(1);
	});

	test("returns null and warns when persisted shape is unrecognizable", () => {
		const decoded = decodePersistedKeybindingsState({ state: "garbage" });
		expect(decoded).toBeNull();
		expect(warnSpy).toHaveBeenCalledTimes(1);
	});

	test("round-trips actions that have no default shortcut", () => {
		// `stop-playback` is a valid `TActionWithOptionalArgs` but is not in the
		// defaults table; the validator must still accept it.
		const serialized = serializeKeybindingsState({
			keybindings: new Map([
				["space", "toggle-play"],
				["x", "stop-playback"],
				["b", "toggle-bookmark"],
			]),
			isCustomized: true,
		});

		const decoded = decodePersistedKeybindingsState({ state: serialized });
		expect(decoded).not.toBeNull();
		if (!decoded) throw new Error("Expected round-tripped keybindings");

		expect(decoded.keybindings.get("space")).toBe("toggle-play");
		expect(decoded.keybindings.get("x")).toBe("stop-playback");
		expect(decoded.keybindings.get("b")).toBe("toggle-bookmark");
		expect(warnSpy).not.toHaveBeenCalled();
	});
});

describe("parseImportedKeybindings", () => {
	test("accepts a valid configuration", () => {
		const result = parseImportedKeybindings({
			config: {
				space: "toggle-play",
				x: "stop-playback",
			},
		});

		expect(result.get("space")).toBe("toggle-play");
		expect(result.get("x")).toBe("stop-playback");
	});

	test("throws on non-object input", () => {
		expect(() => parseImportedKeybindings({ config: null })).toThrow(
			/JSON object/,
		);
		expect(() => parseImportedKeybindings({ config: [] })).toThrow(
			/JSON object/,
		);
	});

	test("throws on non-string action values", () => {
		expect(() =>
			parseImportedKeybindings({ config: { space: 42 } }),
		).toThrow(/expected string/);
	});

	test("throws on invalid shortcut keys", () => {
		expect(() =>
			parseImportedKeybindings({
				config: { "shift+bogus": "toggle-play" },
			}),
		).toThrow(/shift\+bogus/);
	});

	test("throws on invalid actions", () => {
		expect(() =>
			parseImportedKeybindings({ config: { space: "not-an-action" } }),
		).toThrow(/not-an-action/);
	});
});

# Actions System

Actions are the trigger layer for user-initiated operations. They connect keyboard shortcuts, UI buttons, and context menus to editor functionality.

## Adding a New Action

### 1. Define the action — `src/lib/actions/definitions.ts`

Add an entry to the `ACTIONS` object:

```typescript
"my-action": {
    description: "What it does",
    category: "editing",           // playback | navigation | editing | selection | history | timeline | controls
    defaultShortcuts: ["ctrl+m"],  // optional
    args: { someValue: "number" }, // optional, only if it takes args
},
```

**If your shortcut uses a special key** (not a letter/digit), check `getPressedKey` in `src/stores/keybindings-store.ts` and add a case if it's missing:

```typescript
if (key === "escape") return "escape";
```

**If your action has a `defaultShortcuts`**, also add a keybindings migration so existing users get it (keybindings are persisted in localStorage — new defaults only apply to fresh installs):

1. Create `src/stores/keybindings/migrations/vN-to-vN+1.ts`:

```typescript
export function vNToVN1({ state }: { state: unknown }): unknown {
    const s = state as { keybindings: Record<string, string>; isCustomized: boolean };
    const keybindings = { ...s.keybindings };
    if (!keybindings["my-key"]) {
        keybindings["my-key"] = "my-action";
    }
    return { ...s, keybindings };
}
```

2. Register it in `src/stores/keybindings/migrations/index.ts` and bump `CURRENT_VERSION`.

### 2. Register the handler — `src/hooks/actions/use-editor-actions.ts`

```typescript
useActionHandler(
    "my-action",
    () => {
        editor.timeline.doSomething();
    },
    undefined, // isActive: MutableRefObject<boolean> | boolean | undefined
);
```

### 3. Register arg types (if needed) — `src/lib/actions/types.ts`

Only required if your action accepts arguments:

```typescript
export type TActionArgsMap = {
    // ...existing actions...
    "my-action": { someValue: number } | undefined; // | undefined = optional args
};
```

## Invoking Actions

Use `invokeAction` for any user-triggered operation (buttons, context menus, etc.):

```typescript
import { invokeAction } from "@/lib/actions";

invokeAction("my-action");
invokeAction("seek-forward", { seconds: 5 });
```

Avoid calling `editor.xxx()` directly from UI components — that bypasses the action layer (toasts, validation feedback, keybinding support).

## The `isActive` parameter

The third argument to `useActionHandler` controls when the handler is active:

- `undefined` — always active
- `true` / `false` — statically enabled/disabled
- `MutableRefObject<boolean>` — reactive, toggled at runtime (e.g. only active when a panel is focused)

import { describe, expect, test } from "bun:test";
import { transformProjectV18ToV19 } from "../transformers/v18-to-v19";
import { asRecord } from "./helpers";

describe("V18 to V19 Migration", () => {
	test("adds canvas size mode and empty remembered custom size defaults", () => {
		const result = transformProjectV18ToV19({
			project: {
				id: "project-v18-defaults",
				version: 18,
				metadata: {
					id: "project-v18-defaults",
					name: "Project",
					createdAt: "2024-01-01T00:00:00.000Z",
					updatedAt: "2024-01-01T00:00:00.000Z",
				},
				settings: {
					fps: 30,
					canvasSize: { width: 1920, height: 1080 },
					originalCanvasSize: { width: 1920, height: 1080 },
					background: { type: "color", color: "#000000" },
				},
				currentSceneId: "scene-main",
				scenes: [],
			},
		});

		expect(result.skipped).toBe(false);
		expect(result.project.version).toBe(19);
		const settings = asRecord(result.project.settings);
		expect(settings.canvasSizeMode).toBe("preset");
		expect(settings.lastCustomCanvasSize).toBeNull();
		expect(settings.originalCanvasSize).toEqual({
			width: 1920,
			height: 1080,
		});
	});

	test("skips projects already on v19", () => {
		const result = transformProjectV18ToV19({
			project: {
				id: "project-v19",
				version: 19,
			},
		});

		expect(result.skipped).toBe(true);
		expect(result.reason).toBe("already v19");
	});

	test("skips projects with no id", () => {
		const result = transformProjectV18ToV19({
			project: {
				version: 18,
				scenes: [],
			},
		});

		expect(result.skipped).toBe(true);
		expect(result.reason).toBe("no project id");
	});
});

/**
 * Type-safe accessors for navigating migration output.
 *
 * Migrations input/output `Record<string, unknown>` because they handle
 * potentially malformed data from older versions. Tests need to inspect
 * specific properties of the migrated result without using type assertions.
 *
 * These helpers narrow through type guards (Array.isArray + a record
 * predicate), so the file contains no unsafe assertions despite turning
 * unknown into concrete shapes.
 */

function describe(value: unknown): string {
	if (value === null) return "null";
	if (Array.isArray(value)) return "array";
	return typeof value;
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function asRecord(value: unknown): Record<string, unknown> {
	if (!isRecord(value)) {
		throw new Error(`Expected record, got ${describe(value)}`);
	}
	return value;
}

export function asArray(value: unknown): unknown[] {
	if (!Array.isArray(value)) {
		throw new Error(`Expected array, got ${describe(value)}`);
	}
	return value;
}

export function asRecordArray(value: unknown): Record<string, unknown>[] {
	return asArray(value).map(asRecord);
}

import { describe, expect, test } from "bun:test";
import { transformProjectV5ToV6 } from "../transformers/v5-to-v6";
import { v5Project } from "./fixtures";
import { asRecordArray } from "./helpers";

describe("V5 to V6 Migration", () => {
	test("converts number bookmarks to Bookmark objects", async () => {
		const result = transformProjectV5ToV6({
			project: v5Project as Parameters<
				typeof transformProjectV5ToV6
			>[0]["project"],
		});

		expect(result.skipped).toBe(false);
		expect(result.project.version).toBe(6);

		const scenes = asRecordArray(result.project.scenes);
		expect(scenes[0].bookmarks).toEqual([
			{ time: 2.0 },
			{ time: 5.5 },
			{ time: 12.0 },
		]);
		expect(scenes[1].bookmarks).toEqual([]);
	});

	test("skips projects that are already v6", () => {
		const firstScene = (v5Project as { scenes: Array<Record<string, unknown>> })
			.scenes[0];
		const result = transformProjectV5ToV6({
			project: {
				...v5Project,
				version: 6,
				scenes: [
					{
						...firstScene,
						bookmarks: [{ time: 2 }, { time: 5 }],
					},
				],
			} as Parameters<typeof transformProjectV5ToV6>[0]["project"],
		});

		expect(result.skipped).toBe(true);
		expect(result.reason).toBe("already v6");
	});

	test("skips projects with no id", () => {
		const result = transformProjectV5ToV6({
			project: {
				version: 5,
				scenes: [],
			} as Parameters<typeof transformProjectV5ToV6>[0]["project"],
		});

		expect(result.skipped).toBe(true);
		expect(result.reason).toBe("no project id");
	});

	test("preserves existing Bookmark objects with note, color, duration", () => {
		const projectWithRichBookmarks = {
			...v5Project,
			version: 5,
			scenes: [
				{
					...(v5Project as { scenes: Array<Record<string, unknown>> })
						.scenes[0],
					bookmarks: [
						{ time: 1, note: "Intro", color: "#ef4444" },
						{ time: 5.5, duration: 2 },
					],
				},
			],
		};

		const result = transformProjectV5ToV6({
			project: projectWithRichBookmarks as Parameters<
				typeof transformProjectV5ToV6
			>[0]["project"],
		});

		expect(result.skipped).toBe(false);
		const mainScene = asRecordArray(result.project.scenes)[0];
		expect(mainScene.bookmarks).toEqual([
			{ time: 1, note: "Intro", color: "#ef4444" },
			{ time: 5.5, duration: 2 },
		]);
	});
});

import { describe, expect, test } from "bun:test";
import { transformProjectV26ToV27 } from "../transformers/v26-to-v27";
import { asRecord, asRecordArray } from "./helpers";

describe("V26 to V27 Migration", () => {
	test("converts custom mask paths from JSON strings to typed point arrays", () => {
		const result = transformProjectV26ToV27({
			project: {
				id: "project-v26-custom-mask",
				version: 26,
				scenes: [
					{
						id: "scene-1",
						tracks: {
							main: {
								id: "track-1",
								type: "video",
								elements: [
									{
										id: "element-1",
										type: "image",
										masks: [
											{
												id: "mask-custom",
												type: "custom",
												params: {
													path: JSON.stringify([
														{
															id: "point-1",
															x: 0,
															y: 0,
															inX: 0,
															inY: 0,
															outX: 0.1,
															outY: 0,
														},
													]),
													closed: false,
												},
											},
											{
												id: "mask-rectangle",
												type: "rectangle",
												params: {
													width: 0.5,
												},
											},
										],
									},
								],
							},
							overlay: [],
							audio: [],
						},
					},
				],
			},
		});

		expect(result.skipped).toBe(false);
		expect(result.project.version).toBe(27);

		const scenes = asRecordArray(result.project.scenes);
		const tracks = asRecord(scenes[0].tracks);
		const mainTrack = asRecord(tracks.main);
		const elements = asRecordArray(mainTrack.elements);
		const masks = asRecordArray(elements[0].masks);
		const customParams = asRecord(masks[0].params);
		const rectangleParams = asRecord(masks[1].params);

		expect(customParams.path).toEqual([
			{
				id: "point-1",
				x: 0,
				y: 0,
				inX: 0,
				inY: 0,
				outX: 0.1,
				outY: 0,
			},
		]);
		expect(rectangleParams.width).toBe(0.5);
	});
});

import { describe, expect, test } from "bun:test";
import { transformProjectV21ToV22 } from "../transformers/v21-to-v22";
import { asRecord, asRecordArray } from "./helpers";

describe("V21 to V22 Migration", () => {
	test("migrates legacy animation channels to bindings and component channels", () => {
		const result = transformProjectV21ToV22({
			project: {
				id: "project-v21-animations",
				version: 21,
				scenes: [
					{
						id: "scene-1",
						tracks: [
							{
								id: "track-1",
								elements: [
									{
										id: "element-1",
										type: "text",
										animations: {
											channels: {
												opacity: {
													valueKind: "number",
													keyframes: [
														{
															id: "opacity-1",
															time: 1,
															value: 0.5,
															interpolation: "linear",
														},
													],
												},
												"transform.position": {
													valueKind: "vector",
													keyframes: [
														{
															id: "position-1",
															time: 2,
															value: { x: 10, y: 20 },
															interpolation: "hold",
														},
													],
												},
												color: {
													valueKind: "color",
													keyframes: [
														{
															id: "color-1",
															time: 3,
															value: "#ff0000",
															interpolation: "linear",
														},
													],
												},
												"effects.effect-1.params.enabled": {
													valueKind: "discrete",
													keyframes: [
														{
															id: "enabled-1",
															time: 4,
															value: true,
															interpolation: "hold",
														},
													],
												},
											},
										},
									},
								],
							},
						],
					},
				],
			},
		});

		expect(result.skipped).toBe(false);
		expect(result.project.version).toBe(22);

		const scenes = asRecordArray(result.project.scenes);
		const tracks = asRecordArray(scenes[0].tracks);
		const elements = asRecordArray(tracks[0].elements);
		const animations = asRecord(elements[0].animations);
		const bindings = asRecord(animations.bindings);
		const channels = asRecord(animations.channels);

		expect(bindings.opacity).toEqual({
			path: "opacity",
			kind: "number",
			components: [{ key: "value", channelId: "opacity:value" }],
		});
		expect(bindings["transform.position"]).toEqual({
			path: "transform.position",
			kind: "vector2",
			components: [
				{ key: "x", channelId: "transform.position:x" },
				{ key: "y", channelId: "transform.position:y" },
			],
		});
		expect(bindings.color).toEqual({
			path: "color",
			kind: "color",
			colorSpace: "srgb-linear",
			components: [
				{ key: "r", channelId: "color:r" },
				{ key: "g", channelId: "color:g" },
				{ key: "b", channelId: "color:b" },
				{ key: "a", channelId: "color:a" },
			],
		});
		expect(bindings["effects.effect-1.params.enabled"]).toEqual({
			path: "effects.effect-1.params.enabled",
			kind: "discrete",
			components: [
				{
					key: "value",
					channelId: "effects.effect-1.params.enabled:value",
				},
			],
		});

		expect(channels["opacity:value"]).toEqual({
			kind: "scalar",
			keys: [
				{
					id: "opacity-1",
					time: 1,
					value: 0.5,
					segmentToNext: "linear",
					tangentMode: "flat",
				},
			],
		});
		expect(channels["transform.position:x"]).toEqual({
			kind: "scalar",
			keys: [
				{
					id: "position-1",
					time: 2,
					value: 10,
					segmentToNext: "step",
					tangentMode: "flat",
				},
			],
		});
		expect(channels["transform.position:y"]).toEqual({
			kind: "scalar",
			keys: [
				{
					id: "position-1",
					time: 2,
					value: 20,
					segmentToNext: "step",
					tangentMode: "flat",
				},
			],
		});
		expect(channels["color:r"]).toEqual({
			kind: "scalar",
			keys: [
				{
					id: "color-1",
					time: 3,
					value: 1,
					segmentToNext: "linear",
					tangentMode: "flat",
				},
			],
		});
		expect(channels["color:g"]).toEqual({
			kind: "scalar",
			keys: [
				{
					id: "color-1",
					time: 3,
					value: 0,
					segmentToNext: "linear",
					tangentMode: "flat",
				},
			],
		});
		expect(channels["color:b"]).toEqual({
			kind: "scalar",
			keys: [
				{
					id: "color-1",
					time: 3,
					value: 0,
					segmentToNext: "linear",
					tangentMode: "flat",
				},
			],
		});
		expect(channels["color:a"]).toEqual({
			kind: "scalar",
			keys: [
				{
					id: "color-1",
					time: 3,
					value: 1,
					segmentToNext: "linear",
					tangentMode: "flat",
				},
			],
		});
		expect(channels["effects.effect-1.params.enabled:value"]).toEqual({
			kind: "discrete",
			keys: [
				{
					id: "enabled-1",
					time: 4,
					value: true,
				},
			],
		});
	});

	test("skips projects already on v22", () => {
		const result = transformProjectV21ToV22({
			project: {
				id: "project-v22",
				version: 22,
			},
		});

		expect(result.skipped).toBe(true);
		expect(result.reason).toBe("already v22");
	});

	test("skips projects not on v21", () => {
		const result = transformProjectV21ToV22({
			project: {
				id: "project-v20",
				version: 20,
			},
		});

		expect(result.skipped).toBe(true);
		expect(result.reason).toBe("not v21");
	});
});

import { describe, expect, test } from "bun:test";
import { transformProjectV30ToV31 } from "../transformers/v30-to-v31";
import { asRecord, asRecordArray } from "./helpers";

describe("V30 to V31 Migration", () => {
	test("renames custom masks to freeform without changing params", () => {
		const params = {
			feather: 0,
			inverted: false,
			strokeColor: "#ffffff",
			strokeWidth: 0,
			strokeAlign: "center",
			path: [{ id: "p1", x: 0, y: 0, inX: 0, inY: 0, outX: 0, outY: 0 }],
			closed: true,
			centerX: 0,
			centerY: 0,
			rotation: 0,
			scale: 1,
		};

		const result = transformProjectV30ToV31({
			project: {
				id: "project-v30-freeform",
				version: 30,
				scenes: [
					{
						tracks: {
							main: {
								elements: [
									{
										id: "image-1",
										type: "image",
										masks: [{ id: "mask-1", type: "custom", params }],
									},
								],
							},
						},
					},
				],
			},
		});

		expect(result.skipped).toBe(false);
		expect(result.project.version).toBe(31);
		const scene = asRecordArray(result.project.scenes)[0];
		const tracks = asRecord(scene.tracks);
		const main = asRecord(tracks.main);
		const element = asRecordArray(main.elements)[0];
		const mask = asRecordArray(asRecord(element).masks)[0];
		expect(mask).toMatchObject({
			id: "mask-1",
			type: "freeform",
			params,
		});
		expect(asRecord(mask).legacyType).toBeUndefined();
	});

